"use client";

import * as React from "react";

export type { ChartReactionOptions } from "@/components/ui/chart-reactions";

export type CryptoTick = { t: number; price: number; volume: number };

export function mulberry32(seed: number) {
  let state = seed >>> 0;
  return () => {
    state |= 0;
    state = (state + 0x6d2b79f5) | 0;
    let word = Math.imul(state ^ (state >>> 15), 1 | state);
    word = (word + Math.imul(word ^ (word >>> 7), 61 | word)) ^ word;
    return ((word ^ (word >>> 14)) >>> 0) / 4294967296;
  };
}

export function genTicks(seed: number, points: number, start: number, drift: number, vol: number, stepMs = 60000): CryptoTick[] {
  const rand = mulberry32(seed);
  const now = Math.floor(Date.now() / 60000) * 60000;
  let price = start;
  return Array.from({ length: points }, (_, index) => {
    price = Math.max(start * 0.2, price * (1 + drift + (rand() - 0.5) * vol));
    return { t: now - (points - 1 - index) * stepMs, price, volume: Math.round(20 + rand() * 180) };
  });
}

export function nextTick(previous: CryptoTick, seedRef: { rand: () => number }, drift: number, vol: number, stepMs = 60000): CryptoTick {
  const price = Math.max(previous.price * 0.2, previous.price * (1 + drift + (seedRef.rand() - 0.5) * vol));
  return { t: previous.t + stepMs, price, volume: Math.round(20 + seedRef.rand() * 180) };
}

export function movingAverage(values: number[], window: number): (number | null)[] {
  return values.map((_, index) => {
    if (index < window - 1) return null;
    let sum = 0;
    for (let offset = 0; offset < window; offset++) sum += values[index - offset]!;
    return sum / window;
  });
}

export function formatPrice(value: number) {
  const digits = value >= 1000 ? 2 : value >= 10 ? 2 : 4;
  return value.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

export function formatCompactUsd(value: number) {
  if (Math.abs(value) >= 1_000_000_000) return `$${(value / 1_000_000_000).toFixed(2)}B`;
  if (Math.abs(value) >= 1_000_000) return `$${(value / 1_000_000).toFixed(2)}M`;
  if (Math.abs(value) >= 1_000) return `$${(value / 1_000).toFixed(2)}K`;
  return `$${value.toFixed(2)}`;
}

export function useLiveTicks({
  seed = 7,
  points = 120,
  start = 100,
  drift = 0.0004,
  vol = 0.006,
  intervalMs = 1200,
  live = true,
}: {
  seed?: number;
  points?: number;
  start?: number;
  drift?: number;
  vol?: number;
  intervalMs?: number;
  live?: boolean;
} = {}) {
  const randRef = React.useRef<() => number>(mulberry32(seed ^ 0x9e3779b9));
  const [ticks, setTicks] = React.useState<CryptoTick[]>(() => genTicks(seed, points, start, drift, vol));
  const [streaming, setStreaming] = React.useState(live);

  React.useEffect(() => {
    setTicks(genTicks(seed, points, start, drift, vol));
    randRef.current = mulberry32(seed ^ 0x9e3779b9);
  }, [seed, points, start, drift, vol]);

  React.useEffect(() => {
    if (!live || !streaming) return;
    if (typeof document !== "undefined" && document.hidden) return;
    const id = window.setInterval(() => {
      setTicks((current) => {
        if (!current.length) return current;
        const next = nextTick(current[current.length - 1]!, { rand: randRef.current }, drift, vol);
        return [...current.slice(-points + 1), next];
      });
    }, intervalMs);
    return () => window.clearInterval(id);
  }, [live, streaming, intervalMs, points, drift, vol]);

  const last = ticks[ticks.length - 1];
  const first = ticks[0];
  const change = last && first ? (last.price / first.price - 1) * 100 : 0;
  return { ticks, last, change, streaming, setStreaming };
}

"use client";

import * as React from "react";
import {
  Area,
  CartesianGrid,
  ComposedChart as RechartsComposedChart,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

import {
  ChartContainer,
  ChartTooltipContent,
  colorVar,
  type ChartConfig,
} from "@/components/ui/chart";
import { Card } from "@/components/ui/card";
import { ChartSkeleton } from "@/components/ui/chart-reactions";
import { formatPrice, mulberry32, type ChartReactionOptions } from "@/components/ui/crypto-feed";
import { cn } from "@/lib/utils";

const defaultConfig = {
  bids: { label: "Bids", color: "var(--chart-up)" },
  asks: { label: "Asks", color: "var(--destructive)" },
} satisfies ChartConfig;

function buildDepth(seed: number, mid: number, levels: number, step: number) {
  const rand = mulberry32(seed);
  let bidTotal = 0;
  let askTotal = 0;
  const bids = Array.from({ length: levels }, (_, index) => {
    bidTotal += 0.2 + rand() * 3 + (index === 4 ? 9 : 0);
    return { price: mid - (levels - index) * step, bids: bidTotal, asks: null as number | null };
  });
  const asks = Array.from({ length: levels }, (_, index) => {
    askTotal += 0.2 + rand() * 3 + (index === 6 ? 11 : 0);
    return { price: mid + (index + 1) * step, bids: null as number | null, asks: askTotal };
  });
  return { rows: [...bids, ...asks], mid, max: Math.max(bidTotal, askTotal) };
}

export function DepthChart({
  symbol = "BTC/USDT",
  basePrice = 97500,
  tickSize = 25,
  levels = 24,
  seed = 31,
  tickMs = 2500,
  className,
  isLoading,
  reaction,
}: {
  symbol?: string;
  basePrice?: number;
  tickSize?: number;
  levels?: number;
  seed?: number;
  tickMs?: number;
  className?: string;
  isLoading?: boolean;
  reaction?: ChartReactionOptions;
}) {
  const [nonce, setNonce] = React.useState(0);
  const depth = React.useMemo(() => buildDepth(seed + nonce * 131, basePrice, levels, tickSize), [seed, nonce, basePrice, levels, tickSize]);

  React.useEffect(() => {
    const id = window.setInterval(() => {
      if (document.hidden) return;
      setNonce((value) => value + 1);
    }, tickMs);
    return () => window.clearInterval(id);
  }, [tickMs]);

  return (
    <Card className={cn("min-w-0 w-full p-5 sm:p-6", className)} role="region" aria-label={`${symbol} market depth`}>
      <ChartSkeleton isLoading={isLoading}>
        <p className="truncate text-[15px] font-medium tracking-tight">Market depth</p>
        <p className="mt-1 font-mono text-xs tabular-nums text-muted-foreground">
          Mid <span className="text-foreground">${formatPrice(depth.mid)}</span>
        </p>
        <ChartContainer isLoading={isLoading} reaction={reaction} config={defaultConfig} data={depth.rows} variant="plain" className="mt-3 h-64 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <RechartsComposedChart data={depth.rows} margin={{ top: 8, right: 4, left: 4, bottom: 0 }}>
              <CartesianGrid vertical={false} stroke="var(--border)" strokeDasharray="3 5" />
              <XAxis dataKey="price" tickLine={false} axisLine={false} interval="preserveStartEnd" minTickGap={64} tick={{ fill: "var(--muted-foreground)", fontSize: 11 }} tickFormatter={(value: number) => `$${Math.round(value).toLocaleString("en-US")}`} />
              <YAxis orientation="right" width={44} tickLine={false} axisLine={false} tick={{ fill: "var(--muted-foreground)", fontSize: 11 }} />
              <Tooltip
                cursor={{ stroke: "var(--chart-cursor)", strokeWidth: 1 }}
                content={<ChartTooltipContent labelFormatter={(label) => `$${formatPrice(Number(label))}`} />}
              />
              <ReferenceLine x={depth.mid} stroke="var(--muted-foreground)" strokeDasharray="4 4" />
              <Area type="stepAfter" dataKey="bids" stroke={colorVar("bids")} strokeWidth={2} fill={colorVar("bids")} fillOpacity={0.22} dot={false} connectNulls isAnimationActive={false} />
              <Area type="stepBefore" dataKey="asks" stroke={colorVar("asks")} strokeWidth={2} fill={colorVar("asks")} fillOpacity={0.22} dot={false} connectNulls isAnimationActive={false} />
            </RechartsComposedChart>
          </ResponsiveContainer>
        </ChartContainer>
        <div className="mt-2 flex items-center gap-4 text-xs text-muted-foreground">
          <span className="flex items-center gap-1.5"><span className="size-2 rounded-[2px] bg-chart-up" aria-hidden />Bids</span>
          <span className="flex items-center gap-1.5"><span className="size-2 rounded-[2px] bg-destructive" aria-hidden />Asks</span>
        </div>
      </ChartSkeleton>
    </Card>
  );
}
